    private var preview: Window? = null
    // Count matching catalogue entries without retaining an ever-growing results history.
    fun countMatches(query: String): Int {
        var count: Int = 0
        val needle: String = query.lowercase(java.util.Locale.ROOT)
        for (i in 0 until materials.size) {
            if (materials[i].lowercase(java.util.Locale.ROOT).contains(needle)) {
