    // detail panel, footer and rows beyond the visible viewport.
    fun click(event: ScreenEvent): Boolean {
        if (event.getCode() != 0 || event.getX() < 20 || event.getX() >= 270 || event.getY() < 120) {
            return false
        }
        val row: Int = (event.getY() - 120) / 24
        if (row >= rows(event.getHeight())) {
            return false
        }
        val target: Int = event.getState().integer("first") + row
        var matched: Int = 0
        val query: String = event.widget("search")
                .getText()
                .lowercase(java.util.Locale.ROOT)
        for (i in 0 until materials.size) {
            val value: String = materials[i]
            if (value.lowercase(java.util.Locale.ROOT).contains(query)) {
                if (matched == target) {
                    selection = value
                    return true
                }
                matched = matched + 1
            }
        }
        return false
    }

    // Scroll a bounded number of rows. Drawing clamps the upper limit against the current query.
    fun scroll(event: ScreenEvent): Boolean {
        var step: Int = 1
        if (event.getCode() > 0) {
            step = -1
        }
        event.getState()
                .integer("first",
            maxInt(0,
            event.getState()
            .integer("first") + step * 3))
        return true
    }

    // Close only this file's owned window. Closing also emits the screen close callback.
    // Call on the client thread; repeated calls are harmless. Never use global closeAll for addon cleanup.
    fun close(): Unit {
        if (preview != null) {
            preview!!.close()
        }
        preview = null
        if (owned != null) {
            owned!!.close()
        }
        owned = null
    }

}

