            .shadow(false)
            .skin("normal",
            -15062988,
            -13614255,
            -1445387,
            1)
            .skin("hovered",
            -13612969,
            -10037571,
            -1445387,
            1);
        screen.button("Cancel",
            188,
            150,
            100,
